package com.gerenciadorrural.modules.inventory.api;
import com.gerenciadorrural.modules.inventory.application.InventoryService.*; import com.gerenciadorrural.shared.api.error.ApiErrorResponse; import com.gerenciadorrural.shared.observability.RequestContextFilter; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.List;
@RestControllerAdvice(assignableTypes=InventoryController.class) class InventoryExceptionHandler {private ResponseEntity<ApiErrorResponse> e(HttpStatus s,String c,HttpServletRequest r){Object id=r.getAttribute(RequestContextFilter.REQUEST_ID_ATTRIBUTE);return ResponseEntity.status(s).cacheControl(CacheControl.noStore()).body(new ApiErrorResponse(c,"A operação de estoque não pôde ser concluída",s.value(),id==null?null:id.toString(),List.of(),Instant.now()));}@ExceptionHandler(Invalid.class)ResponseEntity<ApiErrorResponse> invalid(HttpServletRequest r){return e(HttpStatus.BAD_REQUEST,"INVENTORY_COMMAND_INVALID",r);}@ExceptionHandler(Forbidden.class)ResponseEntity<ApiErrorResponse> forbidden(HttpServletRequest r){return e(HttpStatus.FORBIDDEN,"INVENTORY_FORBIDDEN",r);}@ExceptionHandler(NotFound.class)ResponseEntity<ApiErrorResponse> product(HttpServletRequest r){return e(HttpStatus.NOT_FOUND,"INVENTORY_PRODUCT_NOT_FOUND",r);}@ExceptionHandler(LocationNotFound.class)ResponseEntity<ApiErrorResponse> location(HttpServletRequest r){return e(HttpStatus.NOT_FOUND,"INVENTORY_LOCATION_NOT_FOUND",r);}@ExceptionHandler(MovementNotFound.class)ResponseEntity<ApiErrorResponse> movement(HttpServletRequest r){return e(HttpStatus.NOT_FOUND,"INVENTORY_MOVEMENT_NOT_FOUND",r);}@ExceptionHandler(ProductInUse.class)ResponseEntity<ApiErrorResponse> used(HttpServletRequest r){return e(HttpStatus.CONFLICT,"INVENTORY_PRODUCT_IN_USE",r);}@ExceptionHandler(LocationNotEmpty.class)ResponseEntity<ApiErrorResponse> nonempty(HttpServletRequest r){return e(HttpStatus.CONFLICT,"INVENTORY_LOCATION_NOT_EMPTY",r);}@ExceptionHandler(Insufficient.class)ResponseEntity<ApiErrorResponse> stock(HttpServletRequest r){return e(HttpStatus.CONFLICT,"INVENTORY_INSUFFICIENT_STOCK",r);}@ExceptionHandler(IdempotencyConflict.class)ResponseEntity<ApiErrorResponse> idem(HttpServletRequest r){return e(HttpStatus.CONFLICT,"INVENTORY_OPERATION_IDEMPOTENCY_CONFLICT",r);}@ExceptionHandler(Conflict.class)ResponseEntity<ApiErrorResponse> conflict(HttpServletRequest r){return e(HttpStatus.CONFLICT,"INVENTORY_MOVEMENT_CONFLICT",r);}}
